//! Cargo-driven `atl80.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x77270000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff69000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff69000000u64)),
        o => panic!("atl80-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["dll/win32/atl80/atl_lib_t.o", "engine:uuid", "engine:wine", "engine:oldnames", "import:oleaut32", "import:user32", "import:ole32", "import:gdi32", "import:advapi32", "import:advapi32_vista", "import:shlwapi", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        "x86_64" => &["dll/win32/atl80/atl_lib_t.o", "engine:uuid", "engine:wine", "engine:oldnames", "import:oleaut32", "import:user32", "import:ole32", "import:gdi32", "import:advapi32", "import:advapi32_vista", "import:shlwapi", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        "aarch64" => &["dll/win32/atl80/atl_lib_t.o", "engine:uuid", "engine:wine", "engine:oldnames", "import:oleaut32", "import:user32", "import:ole32", "import:gdi32", "import:advapi32", "import:advapi32_vista", "import:shlwapi", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .c_from_compile_db("atl80_shims", &["dll/win32/atl/atl.c", "dll/win32/atl80/atl80.c", "dll/win32/atl/atl_ax.c", "dll/win32/atl/registrar.c"])
        .spec2def("dll/win32/atl80/atl80.spec", "atl80.dll")
        .spec_stubs()
        .import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/advapi32_vista/advapi32_vista.spec", "advapi32_vista.dll", "advapi32_vista")
        .import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
